def find_length(binary_string):
    def max_diff_substring(s):
        # Convert '0' to +1 and '1' to -1
        transformed = [1 if char == '0' else -1 for char in s]

        # Apply Kadane's algorithm to find the maximum sum subarray
        max_diff = 0
        current_sum = 0

        for value in transformed:
            current_sum += value
            if current_sum > max_diff:
                max_diff = current_sum
            if current_sum < 0:
                current_sum = 0

        return max_diff

    return max_diff_substring(binary_string)

# Example test
assert find_length("11000010001") == 6
