def find_kth(arr1, arr2, k):
    def kth_element(arr1, arr2, k):
        # If one array is empty, return the k-th element from the other array
        if not arr1:
            return arr2[k - 1]
        if not arr2:
            return arr1[k - 1]

        # If k == 1, return the smallest element from both arrays
        if k == 1:
            return min(arr1[0], arr2[0])

        # Divide k into two parts
        idx1 = min(len(arr1), k // 2) - 1
        idx2 = min(len(arr2), k // 2) - 1

        if arr1[idx1] <= arr2[idx2]:
            return kth_element(arr1[idx1 + 1:], arr2, k - (idx1 + 1))
        else:
            return kth_element(arr1, arr2[idx2 + 1:], k - (idx2 + 1))

    return kth_element(arr1, arr2, k)

# Example usage
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
